package httpapi

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"

	"github.com/hkjang/moina/backend/internal/model"
	"github.com/hkjang/moina/backend/internal/secure"
	"github.com/hkjang/moina/backend/internal/store"
)

// A Moim the caller may not join (missing slug, private) and a failed INSERT are
// different outcomes: the first is the caller's mistake and stays 404 not_found, the
// second is a storage problem the operator must be able to tell apart, so it must be
// 500 storage_error like the leave path already reports.
func TestPostgreSQLJoinMoimSeparatesStorageErrorFromNotFound(t *testing.T) {
	dsn := os.Getenv("MOINA_TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("MOINA_TEST_POSTGRES_DSN is not set")
	}
	ctx := t.Context()
	repository, err := store.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(repository.Close)
	secrets, err := secure.New(bytes.Repeat([]byte{61}, 32))
	if err != nil {
		t.Fatal(err)
	}

	suffix := time.Now().UnixNano()
	ownerID := fmt.Sprintf("usr_join_owner_%d", suffix)
	joinerID := fmt.Sprintf("usr_join_member_%d", suffix)
	// The trigger below makes PostgreSQL refuse exactly this user's membership row, so
	// the request travels the real handler → pgx → server path and fails inside the
	// INSERT itself instead of through a hand-injected double.
	poisonID := fmt.Sprintf("usr_join_poison_%d", suffix)
	userIDs := []string{ownerID, joinerID, poisonID}
	publicMoimID := fmt.Sprintf("moim_join_public_%d", suffix)
	privateMoimID := fmt.Sprintf("moim_join_private_%d", suffix)
	publicSlug := fmt.Sprintf("join-public-%d", suffix)
	privateSlug := fmt.Sprintf("join-private-%d", suffix)
	missingSlug := fmt.Sprintf("join-missing-%d", suffix)
	triggerFn := fmt.Sprintf("moina_test_refuse_join_%d", suffix)
	triggerName := fmt.Sprintf("moina_test_refuse_join_trg_%d", suffix)

	t.Cleanup(func() {
		cleanupContext, cancel := context.WithTimeout(context.Background(), 15*time.Second)
		defer cancel()
		_, _ = repository.Pool().Exec(cleanupContext, fmt.Sprintf(`DROP TRIGGER IF EXISTS %s ON moim_members`, triggerName))
		_, _ = repository.Pool().Exec(cleanupContext, fmt.Sprintf(`DROP FUNCTION IF EXISTS %s()`, triggerFn))
		_, _ = repository.Pool().Exec(cleanupContext, `DELETE FROM outbox_events WHERE aggregate_id=ANY($1::text[])`, userIDs)
		_, _ = repository.Pool().Exec(cleanupContext, `DELETE FROM moims WHERE id=ANY($1::text[])`, []string{publicMoimID, privateMoimID})
		_, _ = repository.Pool().Exec(cleanupContext, `DELETE FROM sessions WHERE user_id=ANY($1::text[])`, userIDs)
		_, _ = repository.Pool().Exec(cleanupContext, `DELETE FROM audit_events WHERE actor_id=ANY($1::text[])`, userIDs)
		_, _ = repository.Pool().Exec(cleanupContext, `DELETE FROM users WHERE id=ANY($1::text[])`, userIDs)
	})

	for _, id := range userIDs {
		username := fmt.Sprintf("u%s", id[len("usr_"):])
		if _, err := repository.Pool().Exec(ctx, `INSERT INTO users(id,username,display_name,roles) VALUES($1,$2,$2,ARRAY['member']::text[])`, id, username); err != nil {
			t.Fatal(err)
		}
	}
	tokens := map[string]string{}
	csrfs := map[string]string{}
	for index, id := range userIDs {
		token := fmt.Sprintf("join-token-%d-%d", index, suffix)
		csrf := fmt.Sprintf("join-csrf-%d-%d", index, suffix)
		if err := repository.CreateSession(ctx, model.Session{
			ID: fmt.Sprintf("session_join_%d_%d", index, suffix), UserID: id,
			TokenHash: secrets.HashToken(token), CSRFHash: secrets.HashToken(csrf),
			ExpiresAt: time.Now().UTC().Add(time.Hour),
		}); err != nil {
			t.Fatal(err)
		}
		tokens[id] = token
		csrfs[id] = csrf
	}
	if _, err := repository.Pool().Exec(ctx, `INSERT INTO moims(id,slug,name,owner_id,visibility) VALUES
		($1,$2,'공개 Moim',$5,'public'),
		($3,$4,'비공개 Moim',$5,'private')`,
		publicMoimID, publicSlug, privateMoimID, privateSlug, ownerID); err != nil {
		t.Fatal(err)
	}
	if _, err := repository.Pool().Exec(ctx, `INSERT INTO moim_members(moim_id,user_id,role) VALUES($1,$2,'owner')`, publicMoimID, ownerID); err != nil {
		t.Fatal(err)
	}
	if _, err := repository.Pool().Exec(ctx, fmt.Sprintf(`CREATE FUNCTION %s() RETURNS trigger LANGUAGE plpgsql AS $$
		BEGIN
			IF NEW.user_id = TG_ARGV[0] THEN
				RAISE EXCEPTION 'moina test: storage refused this membership';
			END IF;
			RETURN NEW;
		END $$`, triggerFn)); err != nil {
		t.Fatal(err)
	}
	if _, err := repository.Pool().Exec(ctx, fmt.Sprintf(`CREATE TRIGGER %s BEFORE INSERT ON moim_members FOR EACH ROW EXECUTE FUNCTION %s(%s)`, triggerName, triggerFn, pgQuoteLiteral(poisonID))); err != nil {
		t.Fatal(err)
	}

	server := New(repository, secrets, "v0.1.35-test")
	handler := server.Handler()
	type apiError struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	}
	join := func(path, userID string) (int, apiError, bool) {
		t.Helper()
		request := httptest.NewRequest(http.MethodPost, path, nil)
		request.Header.Set("X-CSRF-Token", csrfs[userID])
		request.AddCookie(&http.Cookie{Name: SessionCookie, Value: tokens[userID]})
		response := httptest.NewRecorder()
		handler.ServeHTTP(response, request)
		if response.Code == http.StatusOK {
			var envelope struct {
				Data struct {
					Joined bool `json:"joined"`
				} `json:"data"`
			}
			if err := json.Unmarshal(response.Body.Bytes(), &envelope); err != nil {
				t.Fatalf("200 본문을 읽을 수 없습니다: %s", response.Body.String())
			}
			return response.Code, apiError{}, envelope.Data.Joined
		}
		var apiErr apiError
		if err := json.Unmarshal(response.Body.Bytes(), &apiErr); err != nil {
			t.Fatalf("응답 %d 본문을 읽을 수 없습니다: %s", response.Code, response.Body.String())
		}
		return response.Code, apiErr, false
	}
	memberCount := func(moimID, userID string) int {
		t.Helper()
		var count int
		if err := repository.Pool().QueryRow(ctx, `SELECT count(*) FROM moim_members WHERE moim_id=$1 AND user_id=$2`, moimID, userID).Scan(&count); err != nil {
			t.Fatal(err)
		}
		return count
	}

	t.Run("public Moim join succeeds", func(t *testing.T) {
		code, apiErr, joined := join("/api/v1/moims/"+publicSlug+"/join", joinerID)
		if code != http.StatusOK || !joined {
			t.Fatalf("응답 = %d %+v joined=%v", code, apiErr, joined)
		}
		if got := memberCount(publicMoimID, joinerID); got != 1 {
			t.Fatalf("멤버 행 수 = %d", got)
		}
	})

	t.Run("re-join of an existing member stays 200", func(t *testing.T) {
		code, apiErr, joined := join("/api/v1/moims/"+publicSlug+"/join", joinerID)
		if code != http.StatusOK || !joined {
			t.Fatalf("응답 = %d %+v joined=%v", code, apiErr, joined)
		}
		if got := memberCount(publicMoimID, joinerID); got != 1 {
			t.Fatalf("멤버 행 수 = %d", got)
		}
	})

	t.Run("owner re-join via members alias stays 200", func(t *testing.T) {
		code, apiErr, joined := join("/api/v1/moims/"+publicSlug+"/members", ownerID)
		if code != http.StatusOK || !joined {
			t.Fatalf("응답 = %d %+v joined=%v", code, apiErr, joined)
		}
	})

	t.Run("missing slug stays 404 not_found", func(t *testing.T) {
		code, apiErr, _ := join("/api/v1/moims/"+missingSlug+"/join", joinerID)
		if code != http.StatusNotFound || apiErr.Code != "not_found" || apiErr.Message != "가입할 수 있는 공개 Moim을 찾을 수 없습니다" {
			t.Fatalf("응답 = %d %+v", code, apiErr)
		}
	})

	t.Run("private Moim stays 404 not_found", func(t *testing.T) {
		code, apiErr, _ := join("/api/v1/moims/"+privateSlug+"/join", joinerID)
		if code != http.StatusNotFound || apiErr.Code != "not_found" || apiErr.Message != "가입할 수 있는 공개 Moim을 찾을 수 없습니다" {
			t.Fatalf("응답 = %d %+v", code, apiErr)
		}
		if got := memberCount(privateMoimID, joinerID); got != 0 {
			t.Fatalf("비공개 Moim에 멤버 행이 생겼습니다: %d", got)
		}
	})

	t.Run("failed INSERT is 500 storage_error", func(t *testing.T) {
		code, apiErr, _ := join("/api/v1/moims/"+publicSlug+"/join", poisonID)
		if code != http.StatusInternalServerError || apiErr.Code != "storage_error" {
			t.Fatalf("저장 오류가 감춰졌습니다: %d %+v", code, apiErr)
		}
		if got := memberCount(publicMoimID, poisonID); got != 0 {
			t.Fatalf("실패한 가입이 남았습니다: %d", got)
		}
	})

	t.Run("failed INSERT via members alias is 500 storage_error", func(t *testing.T) {
		code, apiErr, _ := join("/api/v1/moims/"+publicSlug+"/members", poisonID)
		if code != http.StatusInternalServerError || apiErr.Code != "storage_error" {
			t.Fatalf("저장 오류가 감춰졌습니다: %d %+v", code, apiErr)
		}
	})
}

package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/coreos/go-oidc/v3/oidc"
	"github.com/hkjang/moina/backend/internal/model"
	"github.com/hkjang/moina/backend/internal/observability"
	"github.com/hkjang/moina/backend/internal/store"
)

// MCP를 개인 키 없이 — Keycloak이 발급한 액세스 토큰으로.
//
// The MCP authorization specification (2025-06-18 and later) is OAuth 2.1: the
// MCP server is a *resource server* that publishes where its authorization
// server is (RFC 9728, /.well-known/oauth-protected-resource), and a client
// refused with 401 reads that document, sends the person through Keycloak with
// PKCE, and comes back with an access token whose audience (RFC 8707) is this
// server. Nothing about issuing tokens happens here — Keycloak does that — and
// this file only answers two questions: where is the authorization server, and
// is this token one it issued for us, for an account MOINA already knows.
//
// The personal key stays. A token from SSO is a second door into the same
// room: it authenticates an *existing* account, carries the scopes the
// administrator chose, and passes the same checks a key does. It never creates
// an account — signing in to the web once is what provisions one — and it is
// only accepted on the MCP paths, never on REST, WebSocket or admin routes.

const (
	protectedResourceMetadataPath = "/.well-known/oauth-protected-resource"
	mcpOAuthRealm                 = "MOINA"
	// A JWT far beyond what Keycloak mints is not one; the shape test stops
	// before the verifier would parse it.
	maxMCPOAuthTokenBytes = 32 << 10
)

// mcpOAuthSigningAlgs is the asymmetric set. HS* would let anybody holding the
// public JWKS forge a token, and "none" needs no comment; go-oidc refuses both
// when the list is explicit.
var mcpOAuthSigningAlgs = []string{oidc.RS256, oidc.RS384, oidc.RS512, oidc.ES256, oidc.ES384, oidc.ES512, oidc.PS256, oidc.PS384, oidc.PS512}

// defaultMCPOAuthScopes are the permissions a new personal key gets, so an SSO
// subject starts with exactly what a key would.
func defaultMCPOAuthScopes() []string { return []string{"posts:read", "mcp:use"} }

// isMCPPath names the only routes on which an OAuth bearer is examined. Both
// spellings share the handler and therefore share the challenge.
func isMCPPath(path string) bool {
	return path == "/mcp" || path == "/api/v1/mcp"
}

// looksLikeJWT is the cheap shape test that separates "not a key" from "not a
// token of any kind we accept". A bearer that is neither stays the refusal it
// always was, so a deployment with SSO off says nothing new.
func looksLikeJWT(token string) bool {
	if len(token) > maxMCPOAuthTokenBytes {
		return false
	}
	parts := strings.Split(token, ".")
	return len(parts) == 3 && parts[0] != "" && parts[1] != "" && parts[2] != ""
}

// mcpOAuthState is everything a request needs to know about SSO tokens at
// once: the settings, the identifier this deployment claims, and whether the
// feature is actually in force. Enabled is not the same as active — the
// standard turns the switch into a no-op, with the reason in the log, when the
// issuer, the resource or MCP itself is missing.
type mcpOAuthState struct {
	cfg      model.OIDCConfig
	resource string
	// resourceSource says where the identifier came from, for the admin card.
	resourceSource string
	active         bool
	reason         string
}

func (s *Server) mcpOAuthState(r *http.Request) mcpOAuthState {
	cfg, err := s.oidcConfig(r)
	if err != nil {
		return mcpOAuthState{reason: "OIDC 설정을 읽을 수 없습니다: " + err.Error()}
	}
	return s.mcpOAuthStateFor(r, cfg)
}

func (s *Server) mcpOAuthStateFor(r *http.Request, cfg model.OIDCConfig) mcpOAuthState {
	state := mcpOAuthState{cfg: cfg}
	general, err := s.general(r)
	if err != nil {
		state.reason = "일반 설정을 읽을 수 없습니다: " + err.Error()
		return state
	}
	state.resource, state.resourceSource = mcpOAuthResource(cfg.MCPOAuth, general.PublicBaseURL, r)
	if !cfg.MCPOAuth.Enabled {
		state.reason = "mcp.oauth.enabled가 꺼져 있습니다"
		return state
	}
	api, err := s.apiSettings(r)
	switch {
	case cfg.IssuerURL == "" || cfg.ClientID == "":
		state.reason = "oidc.issuer_url 또는 oidc.client_id가 비어 있습니다"
	case state.resource == "":
		state.reason = "리소스 식별자를 만들 수 없습니다. mcp.oauth.resource 또는 사이트 기본 주소를 설정하세요"
	case err != nil:
		state.reason = "API 접근 설정을 읽을 수 없습니다: " + err.Error()
	case !api.Enabled || !api.MCPEnabled:
		state.reason = "관리자가 API 키 접근 또는 MCP를 꺼 두었습니다"
	default:
		state.active = true
	}
	return state
}

// mcpOAuthResource is the RFC 8707 identifier: what the metadata advertises and
// what a token's aud may name. An explicit setting wins, then the site's public
// base URL — the address clients actually connect to, not the one behind the
// proxy — and only when both are empty the request itself, which anybody can
// spell as they like in a Host header.
func mcpOAuthResource(cfg model.MCPOAuthConfig, publicBaseURL string, r *http.Request) (string, string) {
	if cfg.Resource != "" {
		return cfg.Resource, "explicit"
	}
	if publicBaseURL != "" {
		return strings.TrimRight(publicBaseURL, "/") + "/mcp", "publicBaseUrl"
	}
	if r == nil || r.Host == "" {
		return "", "request"
	}
	scheme := "http"
	if isHTTPS(r) {
		scheme = "https"
	}
	return scheme + "://" + r.Host + "/mcp", "request"
}

// metadataURL is where a refused client is sent to learn the above. RFC 9728
// puts the document for a resource with a path under the well-known prefix plus
// that path, so …/mcp becomes …/.well-known/oauth-protected-resource/mcp.
func (state mcpOAuthState) metadataURL() string {
	parsed, err := url.Parse(state.resource)
	if err != nil || parsed.Host == "" {
		return ""
	}
	return parsed.Scheme + "://" + parsed.Host + protectedResourceMetadataPath + parsed.Path
}

// mcpOAuthStatusView is what the administrator card shows next to the
// switch: the identifier, the two addresses to paste into a client, and why
// the feature is inert when it is.
func (s *Server) mcpOAuthStatusView(r *http.Request, cfg model.OIDCConfig) map[string]any {
	state := s.mcpOAuthStateFor(r, cfg)
	view := map[string]any{"active": state.active, "resource": state.resource, "resourceSource": state.resourceSource, "metadataUrl": state.metadataURL(), "scopes": cfg.MCPOAuth.Scopes}
	if !state.active && cfg.MCPOAuth.Enabled {
		view["reason"] = state.reason
	}
	return view
}

// mcpOAuthProviders caches discovery for the issuer. Discovery is a network
// round trip to Keycloak and the JWKS behind it verifies every token; doing it
// per request would put Keycloak's latency in front of every MCP call. The
// cache is keyed by the issuer together with the outbound policy so a changed
// setting is never served by a provider built under the old one. go-oidc
// refetches the key set on an unknown key id, so key rotation needs nothing
// here.
type mcpOAuthProviders struct {
	mu       sync.Mutex
	key      string
	provider *oidc.Provider
}

func (c *mcpOAuthProviders) put(key string, provider *oidc.Provider) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.key, c.provider = key, provider
}

// mcpOAuthProviderKey is the cache identity of a provider: issuer plus every
// policy input the discovery client is built from.
func mcpOAuthProviderKey(cfg model.OIDCConfig) string {
	return strings.Join([]string{cfg.IssuerURL, strings.Join(cfg.AllowedHosts, ","), strings.Join(cfg.PrivateAllowedHosts, ","), fmt.Sprint(cfg.AllowInsecureHTTP)}, "\n")
}

func (s *Server) mcpOAuthProvider(ctx context.Context, cfg model.OIDCConfig) (*oidc.Provider, error) {
	key := mcpOAuthProviderKey(cfg)
	s.mcpOAuth.mu.Lock()
	defer s.mcpOAuth.mu.Unlock()
	if s.mcpOAuth.provider != nil && s.mcpOAuth.key == key {
		return s.mcpOAuth.provider, nil
	}
	client, err := s.outboundClient(cfg.AllowedHosts, cfg.PrivateAllowedHosts, cfg.AllowInsecureHTTP)
	if err != nil {
		return nil, err
	}
	// Discovery must outlive this request: the provider keeps the context for
	// later key fetches, and the client in it is the policy-bound one.
	discoveryCtx, cancel := context.WithTimeout(oidc.ClientContext(context.WithoutCancel(ctx), client), 10*time.Second)
	defer cancel()
	provider, err := oidc.NewProvider(discoveryCtx, cfg.IssuerURL)
	if err != nil {
		return nil, err
	}
	s.mcpOAuth.key, s.mcpOAuth.provider = key, provider
	return provider, nil
}

// mcpOAuthRefusal says why a bearer was not turned into a principal. The
// message is what the client sees; the error is the original cause and is
// logged by the caller so an operator can tell a bad signature from a wrong
// issuer without the client learning either.
type mcpOAuthRefusal struct {
	reason  string
	message string
	err     error
}

// mcpOAuthClaims are the access-token claims checked beyond what go-oidc
// verifies (signature, issuer, exp, nbf, algorithm).
type mcpOAuthClaims struct {
	Type              string          `json:"typ"`
	AuthorizedParty   string          `json:"azp"`
	Scope             string          `json:"scope"`
	Confirmation      json.RawMessage `json:"cnf"`
	PreferredUsername string          `json:"preferred_username"`
}

// mcpOAuthPrincipal turns a bearer access token into a principal, or says
// exactly why it will not. Nothing here writes: no account, no session, no
// identity link. The subject must already exist from a web sign-in.
func (s *Server) mcpOAuthPrincipal(r *http.Request, state mcpOAuthState, token string) (principal, *mcpOAuthRefusal) {
	ctx := r.Context()
	cfg := state.cfg
	provider, err := s.mcpOAuthProvider(ctx, cfg)
	if err != nil {
		return principal{}, &mcpOAuthRefusal{reason: "discovery", err: err, message: "Keycloak 발급자 정보를 읽지 못해 SSO 토큰을 확인할 수 없습니다. 잠시 후 다시 시도하거나 관리자에게 알리세요"}
	}
	// Signature, issuer, exp, nbf and algorithm are the library's. The
	// audience is checked below by hand because more than one value is
	// acceptable and the library compares aud alone — it does not know azp.
	verified, err := provider.Verifier(&oidc.Config{SkipClientIDCheck: true, SupportedSigningAlgs: mcpOAuthSigningAlgs}).Verify(ctx, token)
	if err != nil {
		return principal{}, &mcpOAuthRefusal{reason: "token", err: err, message: "SSO 액세스 토큰이 유효하지 않습니다(서명·발급자·만료·nbf·알고리즘). 클라이언트에서 다시 로그인하세요"}
	}
	var claims mcpOAuthClaims
	if err := verified.Claims(&claims); err != nil {
		return principal{}, &mcpOAuthRefusal{reason: "claims", err: err, message: "SSO 토큰의 내용을 읽을 수 없습니다"}
	}
	if strings.EqualFold(claims.Type, "ID") {
		return principal{}, &mcpOAuthRefusal{reason: "id_token", err: errors.New("typ=ID"), message: "ID 토큰은 로그인 증거이지 API 자격이 아닙니다. 액세스 토큰을 보내세요"}
	}
	if len(claims.Confirmation) > 0 && string(claims.Confirmation) != "null" {
		return principal{}, &mcpOAuthRefusal{reason: "cnf", err: errors.New("cnf present"), message: "소지자 증명(cnf)이 묶인 토큰은 이 서버가 검증할 수 없습니다"}
	}
	subject := strings.TrimSpace(verified.Subject)
	if subject == "" {
		return principal{}, &mcpOAuthRefusal{reason: "subject", err: errors.New("sub missing"), message: "SSO 토큰에 사용자 식별자(sub)가 없습니다"}
	}
	// Whom the token was minted for. Measured against a real Keycloak 26: an
	// access token issued to a client carries that client in azp and
	// aud: ["account"] — the client id is not in aud, whatever an ID token
	// does. So the binding is "aud names this resource, or aud/azp names a
	// client the administrator trusts". Either is the token being for this
	// deployment rather than passed through from another application in the
	// realm, which is what RFC 8707 guards against. The web sign-in client is
	// trusted too: a token Keycloak issued to MOINA's own client is for MOINA.
	accepted := append([]string{state.resource}, cfg.MCPOAuth.Audience...)
	if cfg.ClientID != "" {
		accepted = append(accepted, cfg.ClientID)
	}
	bound := append(slices.Clone(verified.Audience), claims.AuthorizedParty)
	if !slices.ContainsFunc(bound, func(value string) bool { return value != "" && slices.Contains(accepted, value) }) {
		return principal{}, &mcpOAuthRefusal{
			reason: "audience",
			err:    fmt.Errorf("aud %v / azp %q not accepted", verified.Audience, claims.AuthorizedParty),
			message: fmt.Sprintf("SSO 토큰이 이 서버를 위해 발급된 것이 아닙니다(aud=%v, azp=%q). 관리자가 허용 대상에 %q을(를) 더하거나, Keycloak 클라이언트의 Audience 매퍼에 %q을(를) 넣어야 합니다",
				verified.Audience, claims.AuthorizedParty, firstNonemptyString(claims.AuthorizedParty, "<client id>"), state.resource),
		}
	}
	// The same lookup the web sign-in uses, without the provisioning half. The
	// identity link is by issuer and subject only: the web sign-in never links
	// an SSO subject to a local account by username, and a machine presenting
	// a token is not the moment to start.
	user, err := s.repo.UserByOIDC(ctx, cfg.IssuerURL, subject)
	if store.IsNotFound(err) {
		return principal{}, &mcpOAuthRefusal{reason: "account", err: errors.New("no identity link for subject"), message: "이 SSO 계정은 MOINA에 등록되지 않았거나 비활성입니다. 먼저 웹으로 한 번 로그인하세요"}
	}
	if err == nil && !user.Active {
		return principal{}, &mcpOAuthRefusal{reason: "account", err: errors.New("account inactive"), message: "이 SSO 계정은 MOINA에 등록되지 않았거나 비활성입니다. 먼저 웹으로 한 번 로그인하세요"}
	}
	if err != nil {
		return principal{}, &mcpOAuthRefusal{reason: "storage", err: err, message: "SSO 사용자를 확인할 수 없습니다"}
	}
	permissions, err := s.permissionsForRoles(ctx, user.Roles)
	if err != nil {
		return principal{}, &mcpOAuthRefusal{reason: "storage", err: err, message: "사용자 권한을 불러올 수 없습니다"}
	}
	// The ceiling is the administrator's scope list, not the token's — nobody
	// has to teach Keycloak MOINA's permission vocabulary before MCP works. If
	// a token does carry that vocabulary, only the intersection is granted.
	// Either way the result passes through the account's role permissions
	// exactly as a key's scopes do.
	return principal{User: user, APIKey: true, OAuth: true, Permissions: intersectPermissions(permissions, mcpOAuthGrantedScopes(cfg.MCPOAuth.Scopes, claims.Scope))}, nil
}

func mcpOAuthGrantedScopes(configured []string, tokenScope string) []string {
	tokenScopes := strings.Fields(tokenScope)
	if !slices.ContainsFunc(tokenScopes, func(scope string) bool { return slices.Contains(configured, scope) }) {
		return configured
	}
	granted := make([]string, 0, len(configured))
	for _, scope := range configured {
		if slices.Contains(tokenScopes, scope) {
			granted = append(granted, scope)
		}
	}
	return granted
}

// logMCPOAuthRefusal keeps the original cause where the client cannot see
// it. The token itself is never logged.
func logMCPOAuthRefusal(r *http.Request, refusal *mcpOAuthRefusal) {
	observability.Logger(r.Context()).WarnContext(r.Context(), "MCP SSO 토큰 거부", "reason", refusal.reason, "error", refusal.err, "path", r.URL.Path)
}

// mcpOAuthChallenge turns a 401 on an MCP path into an invitation: the client
// reads resource_metadata and starts the OAuth flow from there. It is only
// attached on MCP paths and only while SSO tokens are in force — a REST 401
// with this header would send browsers and other clients somewhere wrong, and
// a deployment with the feature off must answer as it always has.
func mcpOAuthChallenge(w http.ResponseWriter, state mcpOAuthState, refused bool) {
	if !state.active {
		return
	}
	header := fmt.Sprintf(`Bearer realm=%q, resource_metadata=%q`, mcpOAuthRealm, state.metadataURL())
	if refused {
		header += `, error="invalid_token"`
	}
	w.Header().Set("WWW-Authenticate", header)
}

// protectedResourceMetadata is RFC 9728: the document a refused MCP client
// reads to find the authorization server. Public by design — it says where to
// sign in, not who is signed in — and answered as a bare document rather than
// the product's {data:…} envelope, because the reader is an OAuth client
// library. With the feature off it is 404: metadata that points at a server
// whose tokens are then refused would trap clients in a login loop.
func (s *Server) protectedResourceMetadata(w http.ResponseWriter, r *http.Request) {
	state := s.mcpOAuthState(r)
	if !state.active {
		if state.cfg.MCPOAuth.Enabled {
			observability.Logger(r.Context()).WarnContext(r.Context(), "MCP SSO(OAuth)가 켜져 있지만 동작하지 않습니다", "reason", state.reason)
		}
		writeError(w, http.StatusNotFound, "mcp_oauth_disabled", "이 서버의 MCP는 SSO 토큰을 받지 않습니다. 개인 API·MCP 키(mk_)를 사용하세요")
		return
	}
	general, err := s.general(r)
	if err != nil {
		writeError(w, http.StatusServiceUnavailable, "settings_unavailable", "서비스 설정을 확인할 수 없습니다")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Cache-Control", "public, max-age=300")
	_ = json.NewEncoder(w).Encode(map[string]any{
		"resource":                 state.resource,
		"authorization_servers":    []string{state.cfg.IssuerURL},
		"bearer_methods_supported": []string{"header"},
		"scopes_supported":         state.cfg.MCPOAuth.Scopes,
		"resource_name":            general.ServiceName + " MCP",
	})
}
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/hkjang/moina/backend/internal/analytics"
	"github.com/hkjang/moina/backend/internal/outbound"
	"github.com/hkjang/moina/backend/internal/secure"
	"github.com/hkjang/moina/backend/internal/store"
)

const (
	settingAnalytics = "analytics.tracking"

	// cspReportPath is where browsers post the requests the content security
	// policy refused. It is unauthenticated because the browser sends the
	// report without credentials, and it keeps nothing but a bounded list of
	// origins in memory.
	cspReportPath = "/api/v1/analytics/csp-report"
	// maxReportBytes keeps the unauthenticated endpoint from being used to push
	// large bodies at the server.
	maxReportBytes = 8 * 1024
	// maxMomentoProxyBytes bounds one forwarded tracker event. A page view is a
	// few hundred bytes of JSON.
	maxMomentoProxyBytes = 64 * 1024
	momentoProxyTimeout  = 10 * time.Second

	// basePagePolicy is the policy every page has always carried. Tracking only
	// ever appends to it and only while it is switched on.
	basePagePolicy = "default-src 'self'; img-src 'self' data: blob:; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self' ws: wss:; frame-ancestors 'none'; base-uri 'self'; form-action 'self'"
	// apiPolicy is for responses that are never a page: JSON, metrics, the
	// MCP stream, proxied tracker traffic. img-src and media-src stay so an
	// attachment opened directly in a tab still renders.
	apiPolicy = "default-src 'none'; img-src 'self'; media-src 'self'; frame-ancestors 'none'"
)

// nonceKey carries the per-request script nonce from the security middleware
// to the SPA handler so the policy header and the injected snippet agree.
type nonceKey struct{}

func requestNonce(r *http.Request) string {
	value, _ := r.Context().Value(nonceKey{}).(string)
	return value
}

// pagePath reports whether a request can be answered with the web app shell.
// Everything else gets the narrow API policy and never a tracking snippet.
func pagePath(path string) bool {
	if path == "/mcp" || path == "/healthz" || path == "/readyz" || path == "/metrics" {
		return false
	}
	if strings.HasPrefix(path, "/api/") || path == analytics.MomentoProxyPath || strings.HasPrefix(path, analytics.MomentoProxyPath+"/") {
		return false
	}
	return true
}

// analyticsConfigContext reads the tracking setting. Any failure — no
// repository, a storage error, a malformed payload — is treated as "tracking
// off" so a settings outage never changes what a page is allowed to run.
func (s *Server) analyticsConfigContext(ctx context.Context) analytics.Config {
	cfg := analytics.Default()
	payload, err := s.analyticsPayload(ctx)
	if err != nil {
		if !store.IsNotFound(err) {
			slog.WarnContext(ctx, "방문 추적 설정을 읽을 수 없어 추적을 끈 채로 응답합니다", "error", err)
		}
		return cfg
	}
	if json.Unmarshal(payload, &cfg) != nil {
		return analytics.Default()
	}
	analytics.Normalize(&cfg)
	if cfg.Validate() != nil {
		return analytics.Default()
	}
	return cfg
}

// analyticsPayload reads the stored setting. Without a repository — tests and
// embedded callers — only a primed cache can supply a configuration.
func (s *Server) analyticsPayload(ctx context.Context) (json.RawMessage, error) {
	if s.repo == nil {
		if s.settings != nil {
			if entry, ok := s.settings.get(settingAnalytics, time.Now()); ok && !entry.missing {
				return entry.payload, nil
			}
		}
		return nil, store.ErrNotFound
	}
	return s.cachedSettingPayload(ctx, settingAnalytics)
}

// pagePolicy keeps the strict page policy and adds only what the configured
// snippet needs: the nonce for its script tags, the origins it loads from and
// posts to, and a report-uri so whatever is still refused becomes visible.
func pagePolicy(cfg analytics.Config, path, nonce string) string {
	if !cfg.Active(path) || nonce == "" {
		return basePagePolicy
	}
	sources := cfg.PolicySources()
	scripts := append([]string{"'self'", "'nonce-" + nonce + "'"}, sources.Scripts...)
	connects := append([]string{"'self'", "ws:", "wss:"}, sources.Connects...)
	images := append([]string{"'self'", "data:", "blob:"}, sources.Images...)
	return "default-src 'self'; img-src " + strings.Join(images, " ") +
		"; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src " + strings.Join(scripts, " ") +
		"; connect-src " + strings.Join(connects, " ") +
		"; frame-ancestors 'none'; base-uri 'self'; form-action 'self'; report-uri " + cspReportPath
}

// contentSecurityPolicy decides the header for one request and returns the
// request carrying the nonce the SPA handler must use.
func (s *Server) contentSecurityPolicy(r *http.Request) (string, *http.Request) {
	if !pagePath(r.URL.Path) {
		return apiPolicy, r
	}
	cfg := s.analyticsConfigContext(r.Context())
	if !cfg.Active(r.URL.Path) {
		return basePagePolicy, r
	}
	nonce, err := secure.RandomToken(16)
	if err != nil {
		return basePagePolicy, r
	}
	r = r.WithContext(context.WithValue(r.Context(), nonceKey{}, nonce))
	return pagePolicy(cfg, r.URL.Path, nonce), r
}

// injectSnippet places the markup just before the closing tag of the chosen
// placement, or at the end of the document when that tag is missing.
func injectSnippet(page []byte, snippet, placement string) []byte {
	marker := "</head>"
	if placement == analytics.PlacementBody {
		marker = "</body>"
	}
	text := string(page)
	index := strings.LastIndex(strings.ToLower(text), marker)
	if index < 0 {
		return []byte(text + "\n" + snippet + "\n")
	}
	return []byte(text[:index] + snippet + "\n" + text[index:])
}

type cspReport struct {
	Report struct {
		BlockedURI         string `json:"blocked-uri"`
		ViolatedDirective  string `json:"violated-directive"`
		EffectiveDirective string `json:"effective-directive"`
		DocumentURI        string `json:"document-uri"`
	} `json:"csp-report"`
}

// receiveCSPReport records what a browser refused to load. Reports are always
// answered with 204: a misbehaving page must never see an error from us, and
// an attacker must learn nothing from the response.
func (s *Server) receiveCSPReport(w http.ResponseWriter, r *http.Request) {
	defer w.WriteHeader(http.StatusNoContent)
	if s.violations == nil {
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, maxReportBytes))
	if err != nil || len(body) == 0 {
		return
	}
	var report cspReport
	if json.Unmarshal(body, &report) != nil {
		return
	}
	directive := report.Report.EffectiveDirective
	if directive == "" {
		directive = report.Report.ViolatedDirective
	}
	s.violations.Record(report.Report.BlockedURI, directive, report.Report.DocumentURI)
}

func analyticsView(cfg analytics.Config) map[string]any {
	return map[string]any{
		"enabled": cfg.Enabled, "provider": cfg.Provider,
		"momentoUrl": cfg.MomentoURL, "momentoSiteId": cfg.MomentoSiteID, "momentoProxy": cfg.MomentoProxy, "momentoAllowPrivateNetwork": cfg.MomentoAllowPrivateNetwork,
		"measurementId": cfg.MeasurementID, "matomoUrl": cfg.MatomoURL, "matomoSiteId": cfg.MatomoSiteID,
		"customSnippet": cfg.CustomSnippet, "allowedHosts": cfg.AllowedHosts, "includeAdmin": cfg.IncludeAdmin, "placement": cfg.Placement,
		"providers": analytics.Providers, "maxSnippetBytes": analytics.MaxSnippetBytes,
		// snippetPreview shows the administrator what a page will carry, with
		// the nonce left as a placeholder because it differs per request.
		"snippetPreview": cfg.Snippet("{nonce}"),
	}
}

func (s *Server) adminGetAnalytics(w http.ResponseWriter, r *http.Request) {
	cfg := analytics.Default()
	if err := s.loadSetting(r, settingAnalytics, &cfg); err != nil && !store.IsNotFound(err) {
		writeError(w, http.StatusInternalServerError, "storage_error", "방문 추적 설정을 불러올 수 없습니다")
		return
	}
	analytics.Normalize(&cfg)
	writeData(w, http.StatusOK, analyticsView(cfg))
}

func (s *Server) adminPutAnalytics(w http.ResponseWriter, r *http.Request) {
	cfg := analytics.Default()
	if !decodeJSON(w, r, &cfg) {
		return
	}
	if err := s.saveAnalytics(r, &cfg); err != nil {
		var invalid *invalidAnalyticsError
		if errors.As(err, &invalid) {
			writeError(w, http.StatusBadRequest, "invalid_config", invalid.Error())
			return
		}
		writeError(w, http.StatusInternalServerError, "storage_error", "방문 추적 설정을 저장할 수 없습니다")
		return
	}
	s.audit(r, "analytics.config.update", "setting", settingAnalytics, true, map[string]any{"enabled": cfg.Enabled, "provider": cfg.Provider, "momentoProxy": cfg.MomentoProxy, "includeAdmin": cfg.IncludeAdmin, "placement": cfg.Placement, "allowedHosts": cfg.AllowedHosts})
	writeData(w, http.StatusOK, analyticsView(cfg))
}

type invalidAnalyticsError struct{ cause error }

func (e *invalidAnalyticsError) Error() string { return e.cause.Error() }

// saveAnalytics normalizes, validates and stores the configuration. Momento's
// same-origin proxy is an outbound connection, so its address goes through the
// same exact-host policy as the other administrator configured endpoints.
func (s *Server) saveAnalytics(r *http.Request, cfg *analytics.Config) error {
	analytics.Normalize(cfg)
	if err := cfg.Validate(); err != nil {
		return &invalidAnalyticsError{cause: err}
	}
	if cfg.Enabled && cfg.Provider == analytics.ProviderMomento && cfg.MomentoProxy {
		if _, err := momentoPolicy(*cfg); err != nil {
			return &invalidAnalyticsError{cause: err}
		}
	}
	_, err := s.saveSetting(r, settingAnalytics, cfg, false, nil)
	return err
}

// adminListAnalyticsViolations shows which addresses the policy is blocking so
// a snippet can be fixed without reading the browser console.
func (s *Server) adminListAnalyticsViolations(w http.ResponseWriter, r *http.Request) {
	items := []analytics.Violation{}
	if s.violations != nil {
		items = s.violations.List(s.analyticsConfigContext(r.Context()))
	}
	writeData(w, http.StatusOK, map[string]any{"items": items})
}

// adminClearAnalyticsViolations forgets the recorded reports, which is how an
// administrator checks whether a change actually fixed the snippet.
func (s *Server) adminClearAnalyticsViolations(w http.ResponseWriter, r *http.Request) {
	if s.violations != nil {
		s.violations.Forget()
	}
	s.audit(r, "analytics.violations.clear", "setting", settingAnalytics, true, nil)
	w.WriteHeader(http.StatusNoContent)
}

// adminAllowAnalyticsHost adds one blocked origin to the allow list: the
// one-click fix for a listed violation.
func (s *Server) adminAllowAnalyticsHost(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Origin string `json:"origin"`
	}
	if !decodeJSON(w, r, &input) {
		return
	}
	origin := analytics.OriginOf(input.Origin)
	if origin == "" || origin != strings.ToLower(strings.TrimSuffix(strings.TrimSpace(input.Origin), "/")) {
		writeError(w, http.StatusBadRequest, "invalid_origin", "허용할 출처는 https://host[:port] 형태여야 합니다")
		return
	}
	cfg := analytics.Default()
	if err := s.loadSetting(r, settingAnalytics, &cfg); err != nil && !store.IsNotFound(err) {
		writeError(w, http.StatusInternalServerError, "storage_error", "방문 추적 설정을 불러올 수 없습니다")
		return
	}
	cfg.AllowedHosts = analytics.AddAllowedHost(cfg.AllowedHosts, origin)
	if err := s.saveAnalytics(r, &cfg); err != nil {
		var invalid *invalidAnalyticsError
		if errors.As(err, &invalid) {
			writeError(w, http.StatusBadRequest, "invalid_config", invalid.Error())
			return
		}
		writeError(w, http.StatusInternalServerError, "storage_error", "방문 추적 설정을 저장할 수 없습니다")
		return
	}
	s.audit(r, "analytics.allowed_host.add", "setting", settingAnalytics, true, map[string]any{"origin": origin})
	writeData(w, http.StatusOK, analyticsView(cfg))
}

// momentoPolicy builds the outbound policy for the proxy: exactly the
// configured collector authority, private addresses only when the
// administrator said so, plain HTTP only when the address itself says so.
func momentoPolicy(cfg analytics.Config) (outbound.Policy, error) {
	parsed, err := url.Parse(cfg.MomentoURL)
	if err != nil || parsed.Hostname() == "" {
		return outbound.Policy{}, errors.New("수집기 주소가 올바르지 않아 프록시를 열 수 없습니다")
	}
	authority := outbound.EndpointAuthority(cfg.MomentoURL)
	hosts, err := outbound.NormalizeHosts([]string{authority})
	if err != nil {
		return outbound.Policy{}, errors.New("수집기 주소가 올바르지 않아 프록시를 열 수 없습니다")
	}
	policy := outbound.Policy{AllowedHosts: hosts, AllowHTTP: parsed.Scheme == "http"}
	if cfg.MomentoAllowPrivateNetwork {
		private, err := outbound.NormalizePrivateHosts([]string{authority})
		if err != nil {
			return outbound.Policy{}, errors.New("사설망 Momento 수집기는 IP가 아닌 정확한 DNS 이름을 사용해야 합니다")
		}
		policy.PrivateAllowedHosts = private
	}
	return policy, nil
}

// momentoClient reuses one policy-bound client per collector address so the
// proxy keeps its connections instead of opening a pool per tracker event.
func (s *Server) momentoClient(cfg analytics.Config) (*http.Client, error) {
	key := momentoClientKey(cfg)
	s.momentoMu.Lock()
	defer s.momentoMu.Unlock()
	if s.momentoProxyClient != nil && s.momentoProxyKey == key {
		return s.momentoProxyClient, nil
	}
	policy, err := momentoPolicy(cfg)
	if err != nil {
		return nil, err
	}
	client, err := policy.Client(s.client)
	if err != nil {
		return nil, err
	}
	client.Timeout = momentoProxyTimeout
	s.momentoProxyClient, s.momentoProxyKey = client, key
	return client, nil
}

func momentoClientKey(cfg analytics.Config) string {
	if cfg.MomentoAllowPrivateNetwork {
		return cfg.MomentoURL + "\x00private"
	}
	return cfg.MomentoURL + "\x00public"
}

// momentoProxy forwards /momento/* to the configured collector so the tracker
// and its events stay same-origin for the browser. Cookies and authorization
// never cross: the collector sees a visitor, not a MOINA session.
func (s *Server) momentoProxy(w http.ResponseWriter, r *http.Request) {
	cfg := s.analyticsConfigContext(r.Context())
	if !cfg.Enabled || cfg.Provider != analytics.ProviderMomento || !cfg.MomentoProxy {
		writeError(w, http.StatusNotFound, "not_found", "요청한 경로를 찾을 수 없습니다")
		return
	}
	if r.Method != http.MethodGet && r.Method != http.MethodHead && r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "허용되지 않은 메서드입니다")
		return
	}
	client, err := s.momentoClient(cfg)
	if err != nil {
		writeError(w, http.StatusBadGateway, "momento_egress_denied", "Momento 수집기 주소가 아웃바운드 정책에 의해 차단되었습니다")
		return
	}
	suffix := strings.TrimPrefix(r.URL.Path, analytics.MomentoProxyPath)
	if strings.Contains(suffix, "..") {
		writeError(w, http.StatusNotFound, "not_found", "요청한 경로를 찾을 수 없습니다")
		return
	}
	target := cfg.MomentoURL + suffix
	if r.URL.RawQuery != "" {
		target += "?" + r.URL.RawQuery
	}
	ctx, cancel := context.WithTimeout(r.Context(), momentoProxyTimeout)
	defer cancel()
	var body io.Reader
	if r.Method == http.MethodPost {
		body = http.MaxBytesReader(w, r.Body, maxMomentoProxyBytes)
	}
	upstream, err := http.NewRequestWithContext(ctx, r.Method, target, body)
	if err != nil {
		writeError(w, http.StatusBadGateway, "momento_unavailable", "Momento 수집기에 연결할 수 없습니다")
		return
	}
	for _, name := range []string{"Content-Type", "Accept", "Accept-Language", "User-Agent", "Referer"} {
		if value := r.Header.Get(name); value != "" {
			upstream.Header.Set(name, value)
		}
	}
	upstream.Header.Set("X-Forwarded-For", clientIP(r))
	upstream.Header.Set("X-Forwarded-Host", r.Host)
	if isHTTPS(r) {
		upstream.Header.Set("X-Forwarded-Proto", "https")
	} else {
		upstream.Header.Set("X-Forwarded-Proto", "http")
	}
	response, err := client.Do(upstream)
	if err != nil {
		var maxBytes *http.MaxBytesError
		if errors.As(err, &maxBytes) {
			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large", "추적 이벤트가 너무 큽니다")
			return
		}
		writeError(w, http.StatusBadGateway, "momento_unavailable", "Momento 수집기에 연결할 수 없습니다")
		return
	}
	defer response.Body.Close()
	for _, name := range []string{"Content-Type", "Cache-Control", "ETag", "Last-Modified", "Expires", "Vary"} {
		if value := response.Header.Get(name); value != "" {
			w.Header().Set(name, value)
		}
	}
	w.WriteHeader(response.StatusCode)
	if r.Method != http.MethodHead {
		_, _ = io.Copy(w, response.Body)
	}
}

